import{_ as t,a,b as r,c as o}from"./chunks/mech_lunxi_0825.DDsOjSmu.js";import{_ as n,o as e,c as p,a4 as l}from"./chunks/framework.BabNWGMA.js";const k=JSON.parse('{"title":"⚙️ 机械原理 知识点笔记","description":"","frontmatter":{},"headers":[],"relativePath":"subjects/机械原理.md","filePath":"subjects/机械原理.md","lastUpdated":1787614642000}'),g={name:"subjects/机械原理.md"};function m(c,s,i,u,b,h){return e(),p("div",null,[...s[0]||(s[0]=[l('<h1 id="⚙️-机械原理-知识点笔记" tabindex="-1">⚙️ 机械原理 知识点笔记 <a class="header-anchor" href="#⚙️-机械原理-知识点笔记" aria-label="Permalink to &quot;⚙️ 机械原理 知识点笔记&quot;">​</a></h1><blockquote><p>共 <strong>23</strong> 个知识点 · 隔天自动更新</p></blockquote><h2 id="平面机构自由度计算" tabindex="-1">平面机构自由度计算 <a class="header-anchor" href="#平面机构自由度计算" aria-label="Permalink to &quot;平面机构自由度计算&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 40% | <strong>创建:</strong> 2026-08-08 | <strong>最近复习:</strong> 2026-08-15</p></blockquote><blockquote><p>掌握度进度: ████░░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>F=3n-2PL-PH(n=活动构件数,PL=低副数,PH=高副数)。三大陷阱:复合铰链(按构件数-1计低副)、局部自由度(滚子等去掉)、虚约束(重复约束去掉)。运动确定条件:F&gt;0 且 F=原动件数。例题:铰链四杆机构 n=3,PL=4,PH=0 → F=1</p><p><strong>图示:</strong></p><p><img src="'+t+'" alt="平面机构自由度计算 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>铰链四杆机构 n=3,PL=4,PH=0 → F=3×3-2×4=1;原动件1个→运动确定,2个→卡死或不确定</p></details><hr><h2 id="运动副与机构运动简图" tabindex="-1">运动副与机构运动简图 <a class="header-anchor" href="#运动副与机构运动简图" aria-label="Permalink to &quot;运动副与机构运动简图&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 60% | <strong>创建:</strong> 2026-08-08 | <strong>最近复习:</strong> 2026-08-08</p></blockquote><blockquote><p>掌握度进度: ██████░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>构件直接接触并能相对运动的连接叫运动副。低副=面接触(转动副、移动副),承载大耐磨;高副=点/线接触(齿轮副、凸轮副),易磨损但可实现复杂运动规律。运动简图用规定符号表示构件和运动副,忽略形状只反映运动传递关系</p><p><strong>图示:</strong></p><p><img src="'+t+'" alt="运动副与机构运动简图 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>曲柄滑块机构(内燃机):曲柄-机架转动副,曲柄-连杆转动副,连杆-滑块转动副,滑块-机架移动副。n=3,PL=4,PH=0 → F=1</p></details><hr><h2 id="高副低代" tabindex="-1">高副低代 <a class="header-anchor" href="#高副低代" aria-label="Permalink to &quot;高副低代&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 60% | <strong>创建:</strong> 2026-08-11 | <strong>最近复习:</strong> 2026-08-11</p></blockquote><blockquote><p>掌握度进度: ██████░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>高副(点/线接触)用虚拟构件+两个转动副替代,运动不变。转动副中心放在两轮廓曲率中心;接触元素为直线→曲率中心无穷远→转动副变移动副。替代前后F不变(ΔF=3-4+1=0)</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>凸轮-滚子:虚拟杆从凸轮圆心连到滚子中心,两端转动副;平底从动件→移动副</p></details><hr><h2 id="速度瞬心法" tabindex="-1">速度瞬心法 <a class="header-anchor" href="#速度瞬心法" aria-label="Permalink to &quot;速度瞬心法&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 60% | <strong>创建:</strong> 2026-08-11 | <strong>最近复习:</strong> 2026-08-12</p></blockquote><blockquote><p>掌握度进度: ██████░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>瞬心=两构件速度相同的点。转动副中心=瞬心;移动副瞬心在垂直于导路的无穷远;纯滚动高副瞬心在接触点。三心定理:3构件3瞬心共线。同一瞬心:v=ω1·r1=ω2·r2</p><p><strong>图示:</strong></p><p><img src="'+a+'" alt="速度瞬心法 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>四杆机构:ω3=ω1·P13A/P13D;P13=BC线与AD线交点</p></details><hr><h2 id="急回特性与行程速比系数k" tabindex="-1">急回特性与行程速比系数K <a class="header-anchor" href="#急回特性与行程速比系数k" aria-label="Permalink to &quot;急回特性与行程速比系数K&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 70% | <strong>创建:</strong> 2026-08-15 | <strong>最近复习:</strong> 2026-08-15</p></blockquote><blockquote><p>掌握度进度: ███████░░░</p></blockquote><p><strong>核心内容:</strong></p><p>曲柄匀速转,摇杆往返时间不同:工作行程对应180°+θ,回程180°-θ。θ=极位夹角(曲柄与连杆两次共线时曲柄两位置夹角)。K=(180°+θ)/(180°-θ);K&gt;1有急回,θ=0时K=1无急回</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>θ=30°→K=210/150=1.4(回程快40%);θ=36°→K=1.5</p></details><hr><h2 id="铰链四杆机构的基本型式与曲柄存在条件" tabindex="-1">铰链四杆机构的基本型式与曲柄存在条件 <a class="header-anchor" href="#铰链四杆机构的基本型式与曲柄存在条件" aria-label="Permalink to &quot;铰链四杆机构的基本型式与曲柄存在条件&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 70% | <strong>创建:</strong> 2026-08-15 | <strong>最近复习:</strong> 2026-08-15</p></blockquote><blockquote><p>掌握度进度: ███████░░░</p></blockquote><p><strong>核心内容:</strong></p><p>曲柄=能转整圈,摇杆=只能摆动。杆长条件:最短+最长≤其余两杆之和。满足时:最短杆=连架杆→曲柄摇杆;最短杆=机架→双曲柄;最短杆=连杆→双摇杆。不满足→必为双摇杆。连架杆=与机架共用铰链的杆(机架两端)</p><p><strong>图示:</strong></p><p><img src="'+t+'" alt="铰链四杆机构的基本型式与曲柄存在条件 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>杆长2.5/3.5/4.5/5.5(机架):8≤8满足,最短2.5是连架杆→曲柄摇杆</p></details><hr><h2 id="渐开线齿廓与渐开线的性质" tabindex="-1">渐开线齿廓与渐开线的性质 <a class="header-anchor" href="#渐开线齿廓与渐开线的性质" aria-label="Permalink to &quot;渐开线齿廓与渐开线的性质&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 60% | <strong>创建:</strong> 2026-08-18 | <strong>最近复习:</strong> 2026-08-18</p></blockquote><blockquote><p>掌握度进度: ██████░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>渐开线:直线沿基圆作纯滚动时,直线上任一点K的轨迹。性质:①K点的法线必与基圆相切(切点为渐开线在K点的曲率中心);②基圆内无渐开线;③渐开线形状取决于基圆半径,基圆越大渐开线越平直,基圆无穷大时成直线(即齿条齿廓);④同一基圆上任意两条渐开线沿公法线方向的距离相等(法向齿距=基圆齿距)。渐开线齿轮齿廓满足齿廓啮合基本定律→传动比恒定。</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>已知渐开线齿廓上某点K,该点法线与基圆相切于N点,基圆半径rb=50mm,K点距圆心rk=70mm,求压力角αK(提示cosαK=rb/rk)。解:cosαK=50/70=0.7143→αK≈44.4°</p></details><hr><h2 id="渐开线直齿圆柱齿轮的正确啮合条件与重合度" tabindex="-1">渐开线直齿圆柱齿轮的正确啮合条件与重合度 <a class="header-anchor" href="#渐开线直齿圆柱齿轮的正确啮合条件与重合度" aria-label="Permalink to &quot;渐开线直齿圆柱齿轮的正确啮合条件与重合度&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 60% | <strong>创建:</strong> 2026-08-18 | <strong>最近复习:</strong> 2026-08-18</p></blockquote><blockquote><p>掌握度进度: ██████░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>正确啮合条件:两齿轮法向齿距(基圆齿距)必须相等→m1=m2(模数相等)且α1=α2(压力角相等),即标准齿轮模数和压力角相同即可正确啮合。连续传动条件:实际啮合线段长度≥法向齿距,即重合度ε=实际啮合线长度/法向齿距≥1(通常取ε≥1.1~1.3)。重合度越大,传动越平稳,同时啮合的齿对数越多。标准直齿轮ε一般在1.1~1.9之间。</p><p><strong>图示:</strong></p><p><img src="'+r+'" alt="渐开线直齿圆柱齿轮的正确啮合条件与重合度 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>一对标准直齿圆柱齿轮,模数m=3,齿数z1=20,z2=50,压力角α=20°。判断能否正确啮合并估算传动比。解:m1=m2=3、α均20°→满足正确啮合。传动比i12=z2/z1=50/20=2.5(输出轴转速为输入1/2.5)。</p></details><hr><h2 id="渐开线直齿圆柱齿轮的五大基本参数" tabindex="-1">渐开线直齿圆柱齿轮的五大基本参数 <a class="header-anchor" href="#渐开线直齿圆柱齿轮的五大基本参数" aria-label="Permalink to &quot;渐开线直齿圆柱齿轮的五大基本参数&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 60% | <strong>创建:</strong> 2026-08-18 | <strong>最近复习:</strong> 2026-08-18</p></blockquote><blockquote><p>掌握度进度: ██████░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>标准直齿圆柱齿轮的五个基本参数:①齿数z;②模数m=分度圆直径d/齿数z,d=mz,模数已标准化(优先系列1/1.25/1.5/2/2.5/3/4/5/6/8/10);③压力角α=20°(分度圆上标准);④齿顶高系数ha*=1;⑤顶隙系数c*=0.25。分度圆是计算基准圆,其上齿厚=齿槽宽。标准齿轮:分度圆上齿厚s=齿槽宽e=πm/2。齿顶高ha=ha*·m,齿根高hf=(ha*+c*)·m=1.25m,全齿高h=ha+hf=2.25m。</p><p><strong>图示:</strong></p><p><img src="'+r+'" alt="渐开线直齿圆柱齿轮的五大基本参数 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>模数m=2,齿数z=30的标准直齿轮,求分度圆直径d、齿顶圆直径da、齿根圆直径df。解:d=mz=2×30=60mm;da=d+2ha=60+2×2=64mm;df=d-2hf=60-2×(1.25×2)=60-5=55mm。</p></details><hr><h2 id="标准直齿圆柱齿轮的几何尺寸计算" tabindex="-1">标准直齿圆柱齿轮的几何尺寸计算 <a class="header-anchor" href="#标准直齿圆柱齿轮的几何尺寸计算" aria-label="Permalink to &quot;标准直齿圆柱齿轮的几何尺寸计算&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-22 | <strong>最近复习:</strong> 2026-08-22</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>标准齿轮几何尺寸由五大参数唯一确定(m、z、α=20°、ha*=1、c*=0.25)。核心公式:分度圆直径 d=mz;齿顶高 ha=m;齿根高 hf=1.25m;全齿高 h=2.25m;齿顶圆直径 da=m(z+2);齿根圆直径 df=m(z-2.5);齿距 p=πm;标准安装中心距 a=m(z1+z2)/2;传动比 i12=n1/n2=z2/z1=d2/d1。单位一律 mm。注意:分度圆是计算基准,不是实际可见圆。</p><p><strong>图示:</strong></p><p><img src="'+r+'" alt="标准直齿圆柱齿轮的几何尺寸计算 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>标准直齿圆柱齿轮 m=2mm、z=40,求 d、da、df、p。解:d=mz=2x40=80mm;da=m(z+2)=2x42=84mm;df=m(z-2.5)=2x37.5=75mm;p=πm=3.14x2≈6.28mm。再与该轮啮合的一标准齿轮 z2=60,中心距 a=m(z1+z2)/2=2x(40+60)/2=100mm。</p></details><hr><h2 id="渐开线齿轮的根切现象与最少齿数" tabindex="-1">渐开线齿轮的根切现象与最少齿数 <a class="header-anchor" href="#渐开线齿轮的根切现象与最少齿数" aria-label="Permalink to &quot;渐开线齿轮的根切现象与最少齿数&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-25 | <strong>最近复习:</strong> 2026-08-25</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>用范成法(展成法)加工齿轮时,若齿数过少,刀具齿顶线超过啮合极限点N1,会把轮齿根部已切出的渐开线齿廓再切去一部分,称为根切。后果:削弱齿根强度、减小重合度,严重时破坏正确啮合。标准直齿圆柱齿轮(齿顶高系数ha*=1,压力角α=20°)不发生根切的最少齿数 z_min=2ha*/sin^2α=2/sin^220°=17.1,取17。避免根切的措施:①齿数≥17;②采用正变位(x&gt;0);③增大压力角α;④减小齿顶高系数ha*。</p><p><strong>图示:</strong></p><p><img src="'+r+'" alt="渐开线齿轮的根切现象与最少齿数 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>标准直齿圆柱齿轮 z=14 用范成法加工是否产生根切?如何避免?答:z=14&lt;17,会产生根切;可改用正变位齿轮(x&gt;0),或增大压力角(如α=25°)来避免根切。</p></details><hr><h2 id="定轴轮系传动比计算" tabindex="-1">定轴轮系传动比计算 <a class="header-anchor" href="#定轴轮系传动比计算" aria-label="Permalink to &quot;定轴轮系传动比计算&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-25 | <strong>最近复习:</strong> 2026-08-25</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>定轴轮系:所有齿轮几何轴线位置都固定的轮系。传动比计算公式: i_ab = n_a/n_b = (-1)^m x (所有从动轮齿数连乘积)/(所有主动轮齿数连乘积),其中 m 为外啮合齿轮对数;结果为负表示输出轮与输入轮转向相反。惰轮(介轮):只改变转向,不改变传动比大小,每加一个惰轮转向反转一次。含锥齿轮、蜗杆蜗轮的空间定轴轮系不能用 (-1)^m 判向,必须用画箭头法逐对判断转向。</p><p><strong>图示:</strong></p><p><img src="'+o+'" alt="定轴轮系传动比计算 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>轮系各轮齿数:z1=20,z2=40,z2&#39;=20,z3=60,z3&#39;=25,z4=50,n1=1440r/min,求 i_14 与 n4。解:外啮合3对,m=3;i_14=(-1)^3 x (40x60x50)/(20x20x25)=-120000/10000=-12;n4=n1/i_14=1440/(-12)=-120r/min,负号表示轮4与轮1转向相反。</p></details><hr><h2 id="周转轮系-行星轮系-传动比计算" tabindex="-1">周转轮系(行星轮系)传动比计算 <a class="header-anchor" href="#周转轮系-行星轮系-传动比计算" aria-label="Permalink to &quot;周转轮系(行星轮系)传动比计算&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-29 | <strong>最近复习:</strong> 2026-08-29</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>周转轮系中至少有一个齿轮的几何轴线不固定(绕中心轮轴线公转),这种齿轮叫行星轮;支持行星轮的构件叫系杆H(转臂),轴线固定的齿轮叫中心轮。因行星轮既自转又公转,不能直接用定轴轮系公式,核心方法是转化轮系法(反转法):给整个轮系加一个公共转速 -nH,系杆就&quot;静止&quot;了,周转轮系变成假想的定轴轮系,再套定轴公式。转化轮系传动比公式:i13(H) = (n1-nH)/(n3-nH) = (-1)^m * (z2*z3)/(z1*z2) = -z3/z1(式中符号:中心轮1、3转向相反取负号;若含圆锥齿轮则用画箭头法定符号,公式只算大小)。求解步骤:①分清中心轮/行星轮/系杆;②写出转化轮系传动比公式;③代入已知转速(固定构件转速=0)解方程;④求传动比 i1H=n1/nH 并判断转向。常见考法:单级行星轮系 n1/nH = 1 + z3/z1;已知 nH 求 n1、或已知 n1 求 nH、或求系杆H转速。注意:nH 是未知量时把它当代数变量,不要代数值。</p><p><strong>图示:</strong></p><p><img src="'+o+'" alt="周转轮系(行星轮系)传动比计算 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例:内齿圈3固定(z3=100),太阳轮1 z1=20,行星轮2 z2=40,系杆H输入 nH=100 r/min,求 n1 和传动比 i1H。解:转化轮系 i13(H)=(n1-nH)/(n3-nH)=-z3/z1=-100/20=-5;n3=0,故 (n1-100)/(0-100)=-5,得 n1-100=500,n1=600 r/min;i1H=n1/nH=600/100=6&gt;0,轮1与系杆H同向(轮1转得比H快5倍)。记忆:i1H=1+z3/z1=1+5=6,与计算一致。考察方式:华科考研机械原理常以&quot;求行星轮系传动比或某轮转速&quot;出现,必须会列转化轮系方程、正确处理符号与未知转速。</p></details><hr><h2 id="错题重测-复合铰链的自由度计算-机构自由度概念-公式" tabindex="-1">错题重测:复合铰链的自由度计算(机构自由度概念+公式) <a class="header-anchor" href="#错题重测-复合铰链的自由度计算-机构自由度概念-公式" aria-label="Permalink to &quot;错题重测:复合铰链的自由度计算(机构自由度概念+公式)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 10% | <strong>创建:</strong> 2026-08-29 | <strong>最近复习:</strong> 2026-08-29</p></blockquote><blockquote><p>掌握度进度: █░░░░░░░░░</p></blockquote><p><strong>图示:</strong></p><p><img src="'+t+'" alt="错题重测:复合铰链的自由度计算(机构自由度概念+公式) 图示"></p><hr><h2 id="今日新点-定轴轮系中的惰轮-介轮" tabindex="-1">今日新点:定轴轮系中的惰轮(介轮) <a class="header-anchor" href="#今日新点-定轴轮系中的惰轮-介轮" aria-label="Permalink to &quot;今日新点:定轴轮系中的惰轮(介轮)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 20% | <strong>创建:</strong> 2026-08-29 | <strong>最近复习:</strong> 2026-08-29</p></blockquote><blockquote><p>掌握度进度: ██░░░░░░░░</p></blockquote><p><strong>图示:</strong></p><p><img src="'+o+'" alt="今日新点:定轴轮系中的惰轮(介轮) 图示"></p><hr><h2 id="错题重测-局部自由度陷阱-凸轮滚子" tabindex="-1">错题重测:局部自由度陷阱(凸轮滚子) <a class="header-anchor" href="#错题重测-局部自由度陷阱-凸轮滚子" aria-label="Permalink to &quot;错题重测:局部自由度陷阱(凸轮滚子)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 10% | <strong>创建:</strong> 2026-08-30 | <strong>最近复习:</strong> 2026-08-30</p></blockquote><blockquote><p>掌握度进度: █░░░░░░░░░</p></blockquote><p><strong>图示:</strong></p><p><img src="'+t+'" alt="错题重测:局部自由度陷阱(凸轮滚子) 图示"></p><hr><h2 id="错题重测-定轴轮系传动比计算-专项" tabindex="-1">错题重测:定轴轮系传动比计算(专项) <a class="header-anchor" href="#错题重测-定轴轮系传动比计算-专项" aria-label="Permalink to &quot;错题重测:定轴轮系传动比计算(专项)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 10% | <strong>创建:</strong> 2026-08-30 | <strong>最近复习:</strong> 2026-08-30</p></blockquote><blockquote><p>掌握度进度: █░░░░░░░░░</p></blockquote><p><strong>图示:</strong></p><p><img src="'+o+'" alt="错题重测:定轴轮系传动比计算(专项) 图示"></p><hr><h2 id="【机械原理·到期复习】周转轮系-行星轮系-传动比计算" tabindex="-1">【机械原理·到期复习】周转轮系(行星轮系)传动比计算 <a class="header-anchor" href="#【机械原理·到期复习】周转轮系-行星轮系-传动比计算" aria-label="Permalink to &quot;【机械原理·到期复习】周转轮系(行星轮系)传动比计算&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 10% | <strong>创建:</strong> 2026-08-30 | <strong>最近复习:</strong> 2026-08-30</p></blockquote><blockquote><p>掌握度进度: █░░░░░░░░░</p></blockquote><p><strong>图示:</strong></p><p><img src="'+o+'" alt="【机械原理·到期复习】周转轮系(行星轮系)传动比计算 图示"></p><hr><h2 id="复合轮系的传动比计算-分解为定轴-周转两级" tabindex="-1">复合轮系的传动比计算(分解为定轴+周转两级) <a class="header-anchor" href="#复合轮系的传动比计算-分解为定轴-周转两级" aria-label="Permalink to &quot;复合轮系的传动比计算(分解为定轴+周转两级)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-09-01 | <strong>最近复习:</strong> 2026-09-01</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>复合轮系=定轴轮系+周转轮系的组合,不能整体套用公式。解题三步:(1)划分基本轮系:找出行星轮(几何轴线随系杆H转动),与行星轮啮合的太阳轮/内齿圈及其系杆构成一个周转轮系;其余齿轮构成定轴轮系。(2)分别列方程:定轴部分用 i_ab=n_a/n_b=(-1)^m·(各从动齿数连乘/各主动齿数连乘),m为外啮合次数;周转部分用转化轮系法 i_ab^H=(n_a-n_H)/(n_b-n_H)=±(齿数连乘比),符号由转化轮系中的啮合方向决定(画箭头判断)。(3)找联系:双联齿轮(同轴固连)转速相同;同一构件(轴/系杆)转速相同;联立方程组求解。注意:定轴级与周转级之间通过双联齿轮或同一根轴传递转速。</p><p><strong>图示:</strong></p><p><img src="'+o+'" alt="复合轮系的传动比计算(分解为定轴+周转两级) 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例题:z1=20,z2=40,z2&#39;=20,z3=30,z4=80(内齿圈固定),n1=1000r/min,求n_H。解:定轴级1-2:i_12=n1/n2=z2/z1=40/20=2,故n2=n1/2=500r/min;双联n2&#39;=n2=500r/min。周转级2&#39;-3-4(H):转化轮系i_2&#39;4^H=(n2&#39;-nH)/(n4-nH),n4=0(固定);啮合2&#39;→3外啮合(-),3→4内啮合(+),故(500-nH)/(0-nH)=-z4/z2&#39;=-80/20=-4,即(500-nH)/(-nH)=-4→500-nH=4nH→nH=100r/min。验算:代入n2&#39;=500,n4=0,得(500-100)/(0-100)=400/(-100)=-4 ✓ 转向与n1相同。</p></details><hr><h2 id="轮系的功用-定轴-周转-复合轮系的应用场景" tabindex="-1">轮系的功用(定轴+周转+复合轮系的应用场景) <a class="header-anchor" href="#轮系的功用-定轴-周转-复合轮系的应用场景" aria-label="Permalink to &quot;轮系的功用(定轴+周转+复合轮系的应用场景)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-09-01 | <strong>最近复习:</strong> 2026-09-01</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>轮系是若干对齿轮(或蜗杆等)组成的传动系统,与单级齿轮相比有五大功用:(1)实现大传动比:单级齿轮传动比一般不超过5~7,轮系多级串联可达很大传动比(如i=1000以上),且结构紧凑;(2)较远距离传动:两轴相距较远时,用若干中间齿轮(惰轮)过渡,比逐级大齿轮省材料;(3)分路传动:一个主动轴可同时带动多个从动轴(如机床主轴箱、催化裂化装置中一台电机同时驱动多台泵/风机);(4)变速与换向:滑移齿轮在轴上移动换挡改变传动比(汽车变速箱),惰轮还可改变从动轮转向;(5)运动的合成与分解:差动轮系有两个自由度,可把两个输入运动合成一个输出(如机床进给机构),或把一个输入分解为两个输出(汽车差速器:发动机转速分解给左右车轮)。</p><p><strong>图示:</strong></p><p><img src="'+o+'" alt="轮系的功用(定轴+周转+复合轮系的应用场景) 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例题:汽车直线行驶时左右轮转速相同(差速器壳体转一圈,左右半轴各转一圈);转弯时内侧轮转速低、外侧轮转速高,但二者之和恒等于壳体转速的2倍——这就是差动轮系&#39;分解运动&#39;的典型应用。考研常考:指出某装置属于哪种功用(如变速箱=变速换向、差速器=运动分解)。</p></details><hr><h2 id="定轴轮系传动比计算-错题重测·新齿数" tabindex="-1">定轴轮系传动比计算(错题重测·新齿数) <a class="header-anchor" href="#定轴轮系传动比计算-错题重测·新齿数" aria-label="Permalink to &quot;定轴轮系传动比计算(错题重测·新齿数)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 30% | <strong>创建:</strong> 2026-09-03 | <strong>最近复习:</strong> 2026-09-03</p></blockquote><blockquote><p>掌握度进度: ███░░░░░░░</p></blockquote><p><strong>图示:</strong></p><p><img src="'+o+'" alt="定轴轮系传动比计算(错题重测·新齿数) 图示"></p><hr><h2 id="定轴轮系传动比-必测错题·重测·换齿数" tabindex="-1">定轴轮系传动比(必测错题·重测·换齿数) <a class="header-anchor" href="#定轴轮系传动比-必测错题·重测·换齿数" aria-label="Permalink to &quot;定轴轮系传动比(必测错题·重测·换齿数)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 20% | <strong>创建:</strong> 2026-09-03 | <strong>最近复习:</strong> 2026-09-03</p></blockquote><blockquote><p>掌握度进度: ██░░░░░░░░</p></blockquote><p><strong>图示:</strong></p><p><img src="'+o+'" alt="定轴轮系传动比(必测错题·重测·换齿数) 图示"></p><hr><h2 id="周转轮系传动比计算-转化机构法-反转法" tabindex="-1">周转轮系传动比计算(转化机构法/反转法) <a class="header-anchor" href="#周转轮系传动比计算-转化机构法-反转法" aria-label="Permalink to &quot;周转轮系传动比计算(转化机构法/反转法)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-09-05 | <strong>最近复习:</strong> 2026-09-05</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>周转轮系(行星轮系/差动轮系)不能直接用定轴轮系公式,因为行星轮既有自转又有公转。解法:给整个轮系加上一个与系杆H转速相反的公共转速 -nH(反转法/转化机构法),把所有构件&#39;定&#39;在系杆上看,轮系就转化为&#39;假想的定轴轮系&#39;。转化后传动比公式:i13H = (n1-nH)/(n3-nH) = (-1)^m × Z2Z3.../(Z1Z2...)(m为外啮合对数)。关键:公式右侧用转化轮系的齿数比和符号,与原轮系实际转向无关;n 带正负号代入(转向相反取负);若 n3=0(内齿轮固定,行星轮系),则 i1H = 1 + Z3/Z1(系杆与太阳轮的传动比)。解题套路:1分清太阳轮/行星轮/系杆/内齿圈 2写转化机构传动比等式 3代入已知转速(固定件n=0) 4解未知数。</p><p><strong>图示:</strong></p><p><img src="'+t+'" alt="周转轮系传动比计算(转化机构法/反转法) 图示"></p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>差动轮系中,太阳轮1齿数Z1=20,行星轮2齿数Z2=40,内齿圈3齿数Z3=80(2与3内啮合)。系杆H以转速nH=100r/min转动,太阳轮1固定(n1=0),求内齿圈3转速n3。解:转化机构法,对1、3用转化传动比:(n1-nH)/(n3-nH)=(-1)^1×(Z2/Z1)×(Z3/Z2)=-Z3/Z1(轮1-2外啮合1对取负,轮2-3内啮合不改变符号)。代入:n1=0,nH=100 → (0-100)/(n3-100)=-80/20=-4 → -100=-4n3+400 → n3=125r/min。转向:与系杆同向。</p></details><hr>',182)])])}const x=n(g,[["render",m]]);export{k as __pageData,x as default};
